for i, c in enumerate(cand, 1):
    if (c['older'], c['younger']) in seen:
        continue
    assert i in V, i
    v, note, add = V.pop(i)
    out.append(dict(n=i, older=c['older'], younger=c['younger'], older_phil=c['older_phil'], younger_phil=c['younger_phil'],
                    cite=c['cite'], how=c['how'], score=c['score'], verdict=v, note=note, **({'add': add} if add else {})))
assert not V, sorted(V)
